<?php
declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php';
$month=(string)($_GET['month']??date('Y-m')); if(!valid_month($month)) $month=date('Y-m'); $start=$month.'-01'; $end=date('Y-m-d',strtotime($start.' +1 month'));
$s=$pdo->prepare("SELECT COALESCE(SUM(IF(type='income',amount,0)),0) income, COALESCE(SUM(IF(type='expense',amount,0)),0) expenses, COUNT(*) total FROM transactions WHERE transaction_date>=:s AND transaction_date<:e"); $s->execute(['s'=>$start,'e'=>$end]); $sum=$s->fetch(); $income=(float)$sum['income']; $expenses=(float)$sum['expenses'];
$c=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE type='expense' AND transaction_date>=:s AND transaction_date<:e GROUP BY category ORDER BY total DESC"); $c->execute(['s'=>$start,'e'=>$end]); $cats=$c->fetchAll();
$r=$pdo->prepare('SELECT * FROM transactions WHERE transaction_date>=:s AND transaction_date<:e ORDER BY transaction_date DESC,id DESC LIMIT 8'); $r->execute(['s'=>$start,'e'=>$end]); $recent=$r->fetchAll(); $pageTitle='ExpenseWise — Overview'; require __DIR__.'/includes/header.php'; ?>
<div class="app-shell"><?php require __DIR__.'/includes/sidebar.php'; ?><main class="main-area"><header class="topbar"><div><p class="breadcrumb">Workspace / Overview</p><h1>Good money habits start here.</h1></div><a class="button primary" href="create.php">＋ Add transaction</a></header>
<?php if($f=take_flash()):?><div class="notice <?=e($f['type'])?>"><?=e($f['message'])?></div><?php endif;?>
<section class="month-toolbar"><div><span class="eyebrow">YOUR FINANCIAL SNAPSHOT</span><p>Here’s how your month is looking.</p></div><form class="month-picker"><label for="month">Month</label><input id="month" type="month" name="month" value="<?=e($month)?>"><button class="button soft">View</button></form></section>
<section class="summary-grid"><article class="summary-card balance"><span>Net balance</span><strong><?=money($income-$expenses)?></strong><small>Income minus expenses</small></article><article class="summary-card"><span>Total income</span><strong><?=money($income)?></strong><small>Money received this month</small></article><article class="summary-card"><span>Total expenses</span><strong><?=money($expenses)?></strong><small>Money spent this month</small></article><article class="summary-card"><span>Transactions</span><strong><?=(int)$sum['total']?></strong><small>Recorded this month</small></article></section>
<section class="content-grid"><article class="panel"><div class="panel-heading"><div><h2>Spending breakdown</h2><p>Where your money went</p></div><span class="pill">By category</span></div><?php if(!$cats):?><div class="empty"><strong>No expenses yet</strong><p>Add an expense to see your breakdown.</p></div><?php else:?><div class="chart-wrap"><canvas id="spendingChart" aria-label="Expenses by category"></canvas></div><div id="categoryLegend" class="legend"></div><?php endif;?></article><article class="panel"><div class="panel-heading"><div><h2>Monthly insight</h2><p>A quick look at your cash flow</p></div></div><div class="insight-number"><?=$income>0?number_format(max(0,min(100,($income-$expenses)/$income*100)),1).'%':'—'?></div><p class="muted">of recorded income remains after expenses</p><div class="progress"><span style="width:<?=$income>0?max(0,min(100,($income-$expenses)/$income*100)):0?>%"></span></div><div class="insight-row"><span>Income</span><b><?=money($income)?></b></div><div class="insight-row"><span>Expenses</span><b><?=money($expenses)?></b></div><div class="insight-row"><span>Net balance</span><b><?=money($income-$expenses)?></b></div><a class="report-link" href="reports.php?month=<?=e($month)?>">Explore report →</a></article></section>
<section class="panel recent"><div class="panel-heading"><div><h2>Recent transactions</h2><p>Your latest activity for this month</p></div><a class="report-link" href="transactions.php?month=<?=e($month)?>">View all →</a></div><?php if(!$recent):?><div class="empty"><strong>Your story starts with one entry.</strong><p>Add your first income or expense to see it here.</p><a class="button primary" href="create.php">Add transaction</a></div><?php else:?><div class="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>CATEGORY</th><th>DATE</th><th>PAYMENT</th><th class="right">AMOUNT</th></tr></thead><tbody><?php foreach($recent as $t):?><tr><td><b><?=e($t['title'])?></b><small><?=e(ucfirst($t['type']))?></small></td><td><span class="pill"><?=e($t['category'])?></span></td><td><?=e(date('M j, Y',strtotime($t['transaction_date'])))?></td><td><?=e($t['payment_method'])?></td><td class="right <?= $t['type']==='income'?'green':''?>"><?=$t['type']==='income'?'+':'−'?><?=money((float)$t['amount'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><footer class="app-footer">ExpenseWise <span>Personal finance, made clearer.</span></footer></main></div>
<?php if($cats):?><script>window.expenseWiseData=<?=json_encode(['labels'=>array_column($cats,'category'),'values'=>array_map('floatval',array_column($cats,'total'))],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;</script><?php endif;?><?php require __DIR__.'/includes/footer.php';?>
